const body = $json.body ?? {};
const claims = $json.jwtPayload ?? {};
const expectedIssuer = $vars.SUPABASE_JWT_ISSUER;
if (!expectedIssuer) throw new Error('Missing n8n variable: SUPABASE_JWT_ISSUER');
if (!claims.sub) throw new Error('Verified Supabase JWT is missing sub');
if (claims.iss !== expectedIssuer || claims.role !== 'authenticated') throw new Error('JWT was not issued for this Supabase project');
if (body.user_id && body.user_id !== claims.sub) throw new Error('JWT user does not match request user');
for (const field of ['session_id','business','buyer','problem','objections']) if (!body[field]) throw new Error('Missing required field: ' + field);
return [{ json: { session_id: body.session_id, user_id: claims.sub, business: body.business, buyer: body.buyer, problem: body.problem, objections: body.objections } }];

