const source = $input.first().json;
const raw = source.output ?? source.text ?? source;
let generated = raw;
if (typeof raw === 'string') generated = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
if (generated?.output) generated = generated.output;
if (!generated?.persona_name) throw new Error('Avatar IQ output is missing persona_name');
const previous = $('Load Buyer Project').first().json.blueprint ?? {};
const input = $('Verify User and Normalize').first().json;
return [{ json: { ...input, blueprint: { ...previous, ...generated, generated_at: new Date().toISOString() } } }];
